}
.bar-row {
  display: grid;
  grid-template-columns: 160px 1fr 60px;
  align-items: center;
  gap: 16px;
  margin-bottom: 14px;
}
.bar-label {
  font-family: var(--font-accent);
  font-size: 13px;
  letter-spacing: 0.1em;
  color: var(--crowd-white);
  text-transform: uppercase;
}
.bar-track {
  height: 32px;
  background: #2A2A3A;
  position: relative;
}
.bar-fill {
  height: 100%;
  background: var(--reactor-yellow);
  position: relative;
}
.bar-fill::after {
  content: '';
  position: absolute;
  right: -4px; top: 50%;
  transform: translateY(-50%);
  width: 8px; height: 8px;
  background: var(--ignition-orange);
}
.bar-value {
  font-family: var(--font-display);
  font-size: 18px;
  color: var(--reactor-yellow);
  text-align: right;
}

/* Gallery */
.gallery-section {
  background: var(--backstage-charcoal);
  padding: 80px 0;
  border-bottom: 3px solid var(--plasma-magenta);
}
.gallery-section .section-head .eyebrow { color: var(--reactor-yellow); }
.gallery-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}
.milestone-card {
  background: var(--voltage-black);
  border: 1px solid #2A2A3A;
  padding: 28px 28px 28px 28px;
  padding-top: 56px;
  position: relative;
}
.milestone-card:nth-child(1) { min-height: 340px; }
.milestone-card:nth-child(2) { min-height: 280px; }
.milestone-card:nth-child(3) { min-height: 280px; }
.milestone-card:nth-child(4) { min-height: 340px; }
.date-badge {
  position: absolute;
  top: -32px;
  left: 20px;
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--reactor-yellow);
  color: var(--voltage-black);
  font-family: var(--font-display);
  font-size: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 4px solid var(--backstage-charcoal);
}
.team-chip {
  display: inline-block;
  background: var(--circuit-cyan);
  color: var(--voltage-black);
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.18em;
  padding: 3px 8px;
  margin-bottom: 10px;
}
.milestone-card h3 {
  font-size: 20px;
  letter-spacing: -0.01em;
  margin-bottom: 10px;
}
.milestone-card p { font-size: 15px; line-height: 1.6; }

/* Research CTA close */
.research-cta-close {
  background: var(--reactor-yellow);
  padding: 96px 0;
  text-align: center;
}
.research-cta-close .eyebrow {
  color: var(--voltage-black);
  display: block;
  margin-bottom: 16px;
}
.research-cta-close h2 {
  font-size: clamp(40px, 6.5vw, 72px);
  color: var(--voltage-black);
  letter-spacing: -0.03em;
  max-width: 800px;
  margin: 0 auto;
}
.research-cta-close .sub {
  color: rgba(13,13,13,0.82);
  font-size: 17px;
  margin: 20px auto 32px;
  max-width: 600px;
}
.research-cta-close .cta-row { justify-content: center; }

/* ==========================================================================
   CONTACT PAGE
   ========================================================================== */

.contact-header {
  background: var(--voltage-black);
  padding: 120px 0 80px;
  text-align: center;
  min-height: 70vh;
}
.contact-header .eyebrow { display: block; margin-bottom: 20px; }
.contact-header h1 {
  font-size: clamp(40px, 6vw, 72px);
  letter-spacing: -0.03em;
  line-height: 1;
  max-width: 1000px;
  margin: 0 auto;
}
.contact-header h1 .big-word {
  display: block;
  font-size: 1.12em;
}
.contact-header .sub {
  color: var(--poster-cream);
  font-size: 18px;
  margin: 24px auto 40px;
  max-width: 640px;
}
.handshake-illustration {
  margin: 32px auto 0;
  max-width: 560px;
}

/* Contact block (signature) */
.contact-block-section {
  display: grid;
  grid-template-columns: 55fr 45fr;
  min-height: 90vh;
  position: relative;
}
.contact-form-panel {
  background: linear-gradient(135deg, var(--plasma-magenta) 0%, var(--reactor-yellow) 100%);
  padding: 80px 40px 80px 60px;
  position: relative;
  overflow: hidden;
}
.contact-form-panel .eyebrow {
  color: var(--voltage-black);
  display: block;
  margin-bottom: 20px;
}
.contact-form-panel h2 {
  font-size: clamp(36px, 5vw, 72px);
  color: var(--reactor-yellow);
  letter-spacing: -0.03em;
  line-height: 1;
  margin-bottom: 24px;
  position: relative;
  z-index: 3;
  /* overflow bleed effect */
  white-space: nowrap;
}
.contact-form-panel .sub {
  color: var(--voltage-black);
  font-size: 16px;
  margin-bottom: 16px;
  max-width: 540px;
}
.contact-form-panel .body {
  color: var(--voltage-black);
  font-size: 16px;
  margin-bottom: 32px;
  max-width: 540px;
}
.contact-form {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  max-width: 560px;
}
.field-group { display: flex; flex-direction: column; }
.field-group.full { grid-column: 1 / -1; }
.field-group label {
  font-family: var(--font-body);
  font-weight: 700;
  font-size: 13px;
  letter-spacing: 0.1em;
  color: var(--voltage-black);
  text-transform: uppercase;
  margin-bottom: 6px;
}
.field-group input,
.field-group select,
.field-group textarea {
  background: var(--poster-cream);
  border: 2px solid transparent;
  padding: 12px 14px;
  font-family: var(--font-body);
  font-size: 15px;
  color: var(--voltage-black);
  border-radius: 0;
}
.field-group input:focus,
.field-group select:focus,
.field-group textarea:focus {
  outline: none;
  border-bottom-color: var(--ignition-orange);
}
.field-group textarea { min-height: 120px; resize: vertical; }
.form-submit {
  grid-column: 1 / -1;
  width: 100%;
  background: var(--voltage-black);
  color: var(--reactor-yellow);
  font-family: var(--font-display);
  font-size: 20px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 20px;
  border: none;
  cursor: pointer;
  transition: all 0.2s;
}
.form-submit:hover {
  background: var(--reactor-yellow);
  color: var(--voltage-black);
}

.contact-info-panel {
  background: var(--voltage-black);
  padding: 80px 40px;
}
.contact-info-cards {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.info-card {
  background: var(--backstage-charcoal);
  padding: 20px;
  border-top: 3px solid var(--ignition-orange);
  position: relative;
}
.info-card + .info-card.spaced { margin-top: 8px; }
.info-type-chip {
  position: absolute;
  top: 16px;
  right: 16px;
  background: var(--circuit-cyan);
  color: var(--voltage-black);
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.2em;
  padding: 3px 7px;
  text-transform: uppercase;
}
.info-card h3 {
  font-size: 16px;
  letter-spacing: -0.01em;
  margin-bottom: 6px;
  padding-right: 80px;
}
.info-card p { font-size: 15px; line-height: 1.5; margin: 0; }

/* Map */
.map-section {
  background: var(--voltage-black);
}
.map-zone {
  position: relative;
  width: 100%;
  height: 420px;
  background: var(--backstage-charcoal);
  overflow: hidden;
}
.map-zone svg { width: 100%; height: 100%; }
.map-text-zone {
  max-width: 960px;
  margin: 0 auto;
  padding: 60px 32px 80px;
}
.map-text-zone .eyebrow { color: var(--circuit-cyan); display: block; margin-bottom: 12px; }
.map-text-zone h2 {
  font-size: clamp(32px, 4.5vw, 48px);
  letter-spacing: -0.02em;
  margin-bottom: 16px;
}
.map-text-zone .sub { font-size: 17px; margin-bottom: 12px; }
.map-text-zone .body { font-size: 16px; }
.address-callout {
  background: var(--backstage-charcoal);
  border-top: 3px solid var(--reactor-yellow);
  padding: 24px;
  margin-top: 32px;
}
.address-callout .addr {
  font-family: var(--font-display);
  font-size: 20px;
  color: var(--reactor-yellow);
  letter-spacing: -0.01em;
}
.address-callout .hours {
  font-family: var(--font-accent);
  font-size: 14px;
  letter-spacing: 0.15em;
  color: var(--circuit-cyan);
  text-transform: uppercase;
  margin-top: 8px;
}

/* FAQ */
.faq-section {
  background: var(--backstage-charcoal);
  padding: 80px 0;
}
.faq-section .container-narrow .eyebrow {
  color: var(--ignition-orange);
  display: block;
  margin-bottom: 12px;
}
.faq-section h2 {
  font-size: clamp(32px, 5vw, 52px);
  letter-spacing: -0.02em;
  padding-bottom: 16px;
  border-bottom: 4px solid var(--plasma-magenta);
  margin-bottom: 0;
}
.faq-items { margin-top: 0; }
.faq-item {
  border-top: 2px solid var(--voltage-black);
  padding: 24px 0;
  display: grid;
  grid-template-columns: 28px 1fr 28px;
  gap: 24px;
  align-items: start;
}
.faq-item:first-child { border-top: none; }
.faq-num {
  width: 28px;
  height: 28px;
  background: var(--reactor-yellow);
  color: var(--voltage-black);
  font-family: var(--font-accent);
  font-size: 13px;
  display: flex;
  align-items: center;
  justify-content: center;
  letter-spacing: 0.05em;
}
.faq-content h3 {
  font-size: 20px;
  letter-spacing: -0.01em;
  margin-bottom: 12px;
}
.faq-content p { font-size: 16px; line-height: 1.65; }
.faq-plus {
  font-family: var(--font-accent);
  font-size: 24px;
  color: var(--plasma-magenta);
  text-align: right;
}

/* Contact CTA close */
.contact-cta-close {
  background: var(--reactor-yellow);
  padding: 100px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
  min-height: 60vh;
  display: flex;
  align-items: center;
}
.bolt-decor {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  font-family: var(--font-display);
  font-size: 220px;
  color: var(--plasma-magenta);
  opacity: 0.3;
  line-height: 1;
  pointer-events: none;
}
.bolt-decor.left { left: 32px; }
.bolt-decor.right { right: 32px; }
.contact-cta-close .container { position: relative; z-index: 2; }
.contact-cta-close .eyebrow { color: var(--voltage-black); display: block; margin-bottom: 24px; }
.contact-cta-close h2 {
  font-size: clamp(36px, 6vw, 80px);
  color: var(--voltage-black);
  letter-spacing: -0.03em;
  line-height: 0.95;
  max-width: 1100px;
  margin: 0 auto;
}
.contact-cta-close .sub {
  color: var(--voltage-black);
  font-size: 18px;
  margin: 28px auto 40px;
  max-width: 600px;
}
.contact-cta-close .cta-row { justify-content: center; }
.contact-cta-close .btn-outline-dark { border-width: 3px; }

/* ==========================================================================
   RESPONSIVE
   ========================================================================== */

@media (max-width: 1024px) {
  .nav-links { gap: 18px; }
  .nav-links a { font-size: 13px; }

  .hero-inner { grid-template-columns: 1fr; gap: 32px; }
  .hero-visual { margin-right: 0; order: -1; max-width: 70%; margin: 0 auto; }

  .stats-grid { grid-template-columns: repeat(2, 1fr); }
  .feature-grid { grid-template-columns: 1fr; }

  .timeline::before { left: 32px; }
  .timeline-item { grid-template-columns: 64px 1fr; gap: 16px; }
  .timeline-item.left .timeline-content { text-align: left; justify-self: start; }
  .timeline-item.left > div:last-child,
  .timeline-item.right > div:first-child { display: none; }
  .timeline-node { width: 64px; height: 64px; font-size: 12px; }

  .mega-word { font-size: 130px; left: -20px; }
  .about-header-text { padding-left: 140px; }
  .story-grid { grid-template-columns: 1fr; }
  .story-copy { border-right: none; border-bottom: 3px solid var(--ignition-orange); padding-right: 0; padding-bottom: 32px; }
  .team-grid { grid-template-columns: repeat(2, 1fr); }
  .about-stats-grid { grid-template-columns: 1fr; }
  .garage-illustration { width: 280px; right: 12px; bottom: -60px; }

  .dept-header-grid { grid-template-columns: 1fr; }
  .dept-header-right { padding-top: 0; }
  .dept-grid { grid-template-columns: repeat(2, 1fr); }
  .division-grid { grid-template-columns: repeat(2, 1fr); }
  .testimonials-head { margin-left: 0; }
  .testimonials-grid { grid-template-columns: 1fr; }
  .wristband-illustration { position: static; margin-bottom: 16px; }

  .research-header-grid { grid-template-columns: 1fr; }
  .research-illustration { margin-right: 0; max-width: 70%; margin: 0 auto; }
  .projects-grid { grid-template-columns: 1fr; }
  .project-card.last-card { max-width: 100%; }
  .research-stat-row { grid-template-columns: repeat(2, 1fr); }
  .gallery-grid { grid-template-columns: 1fr; }
  .bar-row { grid-template-columns: 100px 1fr 50px; }

  .contact-block-section { grid-template-columns: 1fr; }
  .contact-form-panel h2 { white-space: normal; font-size: 40px; }
  .contact-info-panel { padding: 48px 24px; }
  .bolt-decor { display: none; }
}

@media (max-width: 700px) {
  .container, .container-narrow, .container-wide { padding: 0 20px; }
  .nav-inner { padding: 14px 20px; }
  .nav-links {
    display: none;
    position: absolute;
    top: 100%;
    left: 0; right: 0;
    background: var(--voltage-black);
    flex-direction: column;
    gap: 0;
    border-top: 1px solid #2A2A3A;
    padding: 8px 0;
  }
  .nav-links.open { display: flex; }
  .nav-links li { width: 100%; }
  .nav-links a { display: block; padding: 14px 24px; border-bottom: none; }
  .nav-toggle { display: block; }

  .hero-headline { font-size: 52px; }
  .hero-visual svg { max-width: 80%; }
  .hero-inner { padding: 0 20px; }

  .stats-grid { grid-template-columns: repeat(2, 1fr); gap: 24px; }
  .stat-cell .stat-num { font-size: 56px; }

  .mega-word { display: none; }
  .about-header-text { padding-left: 0; }
  .about-header-text h1 { font-size: 44px; }
  .garage-illustration { position: static; margin: 32px auto 0; }
  .story-block { padding: 80px 0 64px; }
  .values-grid { grid-template-columns: 1fr; }
  .team-grid { grid-template-columns: 1fr; }
  .about-stat-grid { grid-template-columns: 1fr; }

  .dept-grid { grid-template-columns: 1fr; }
  .icon-strip { grid-template-columns: repeat(3, 1fr); }
  .division-grid { grid-template-columns: 1fr; }
  .yellow-band { padding: 24px 20px; margin: 0 -20px; }
  .yellow-band h2 { font-size: 32px; }
  .division-cta-row { justify-content: center; }

  .research-stat-row { grid-template-columns: 1fr; gap: 24px; }
  .bar-row { grid-template-columns: 80px 1fr 40px; }
  .bar-label { font-size: 11px; }

  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
  .footer-meta { flex-direction: column; gap: 8px; }

  .contact-header h1 { font-size: 40px; }
  .contact-form { grid-template-columns: 1fr; }
  .contact-form-panel { padding: 48px 24px; }
  .contact-form-panel h2 { font-size: 36px; }
  .map-zone { height: 260px; }
}

tool_use_result.content:
/* ==========================================================================
   BOLTWORKS — Festival Poster Robotics Club
   Design tokens: Voltage Black, Reactor Yellow, Plasma Magenta,
                  Ignition Orange, Circuit Cyan, Poster Cream,
                  Crowd White, Backstage Charcoal
   ========================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Archivo+Black&family=Archivo:wght@400;500;700&family=Bebas+Neue&display=swap');

:root {
  --voltage-black: #0D0D0D;
  --reactor-yellow: #FFE600;
  --plasma-magenta: #FF1F8E;
  --ignition-orange: #FF5C00;
  --circuit-cyan: #00E5FF;
  --poster-cream: #F5F0DC;
  --crowd-white: #FFFFFF;
  --backstage-charcoal: #1E1E2A;

  --font-display: 'Archivo Black', 'Archivo', sans-serif;
  --font-body: 'Archivo', system-ui, sans-serif;
  --font-accent: 'Bebas Neue', 'Archivo', sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  background: var(--voltage-black);
  color: var(--crowd-white);
  line-height: 1.65;
  font-size: 17px;
  overflow-x: hidden;
}

img, svg { display: block; max-width: 100%; }

a { color: inherit; text-decoration: none; }

/* ---------- Utilities ---------- */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 32px;
}
.container-narrow { max-width: 960px; }
.container-wide { max-width: 1400px; }

.eyebrow {
  font-family: var(--font-accent);
  font-size: 13px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--plasma-magenta);
}

h1, h2, h3, h4 {
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: -0.03em;
  line-height: 0.98;
  color: var(--crowd-white);
}

p { color: var(--poster-cream); }

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-size: 15px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 18px 32px;
  border: 2px solid transparent;
  border-radius: 0;
  cursor: pointer;
  transition: all 0.18s ease;
  white-space: nowrap;
}
.btn-primary {
  background: var(--reactor-yellow);
  color: var(--voltage-black);
}
.btn-primary:hover {
  background: var(--plasma-magenta);
  color: var(--voltage-black);
}
.btn-outline {
  background: transparent;
  color: var(--crowd-white);
  border-color: var(--crowd-white);
}
.btn-outline:hover {
  color: var(--reactor-yellow);
  border-color: var(--reactor-yellow);
}
.btn-outline-yellow {
  background: transparent;
  color: var(--reactor-yellow);
  border-color: var(--reactor-yellow);
}
.btn-outline-yellow:hover {
  background: var(--reactor-yellow);
  color: var(--voltage-black);
}
.btn-dark {
  background: var(--voltage-black);
  color: var(--reactor-yellow);
}
.btn-dark:hover {
  background: var(--plasma-magenta);
  color: var(--crowd-white);
}
.btn-outline-dark {
  background: transparent;
  color: var(--voltage-black);
  border-color: var(--voltage-black);
}
.btn-outline-dark:hover {
  background: var(--voltage-black);
  color: var(--reactor-yellow);
}
.cta-row { display: flex; flex-wrap: wrap; gap: 16px; }

/* ---------- Top Navigation ---------- */
.site-nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13, 13, 13, 0.96);
  border-bottom: 2px solid var(--reactor-yellow);
  backdrop-filter: blur(8px);
}
.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 32px;
  max-width: 1400px;
  margin: 0 auto;
}
.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  font-family: var(--font-display);
  font-size: 22px;
  text-transform: uppercase;
  letter-spacing: -0.02em;
  color: var(--crowd-white);
}
.brand-bolt {
  width: 28px;
  height: 28px;
  fill: var(--reactor-yellow);
  flex-shrink: 0;
}
.brand-mark {
  background: var(--reactor-yellow);
  color: var(--voltage-black);
  padding: 4px 10px 2px;
}
.nav-links {
  display: flex;
  list-style: none;
  gap: 28px;
  align-items: center;
}
.nav-links a {
  font-family: var(--font-accent);
  font-size: 15px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  padding: 6px 4px;
  border-bottom: 2px solid transparent;
  transition: all 0.15s;
}
.nav-links a:hover { color: var(--reactor-yellow); }
.nav-links a.active {
  border-bottom-color: var(--plasma-magenta);
  color: var(--reactor-yellow);
}
.nav-cta {
  background: var(--reactor-yellow);
  color: var(--voltage-black) !important;
  padding: 8px 18px !important;
  border-bottom: none !important;
  font-family: var(--font-display) !important;
  letter-spacing: 0.04em !important;
}
.nav-cta:hover { background: var(--plasma-magenta); color: var(--crowd-white) !important; }
.nav-toggle {
  display: none;
  background: none;
  border: 2px solid var(--reactor-yellow);
  color: var(--reactor-yellow);
  font-family: var(--font-accent);
  padding: 6px 12px;
  font-size: 14px;
  cursor: pointer;
  letter-spacing: 0.15em;
}

/* ---------- Footer ---------- */
.site-footer {
  background: var(--backstage-charcoal);
  border-top: 4px solid var(--reactor-yellow);
  padding: 64px 32px 24px;
}
.footer-grid {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  padding-bottom: 48px;
  border-bottom: 1px solid #2A2A3A;
}
.footer-grid h4 {
  font-family: var(--font-accent);
  font-size: 14px;
  letter-spacing: 0.22em;
  color: var(--reactor-yellow);
