/* ==========================================================================
   HOME PAGE
   ========================================================================== */

/* Hero */
.home-hero {
  position: relative;
  min-height: 100vh;
  background: var(--voltage-black);
  overflow: hidden;
  display: flex;
  align-items: center;
  padding: 120px 0 80px;
}
.home-hero::before {
  content: '';
  position: absolute;
  top: -10%;
  right: -10%;
  width: 70%;
  height: 80%;
  background: radial-gradient(circle, rgba(255, 31, 142, 0.18), transparent 60%);
