}
.feature-card:nth-child(2) { border-top-color: var(--plasma-magenta); }
.feature-card:nth-child(3) { border-top-color: var(--circuit-cyan); }
.feature-card:nth-child(4) { border-top-color: var(--ignition-orange); }
.feature-card:hover { border-top-width: 6px; background: #25252F; }
.feature-tag {
  display: inline-block;
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  padding: 4px 10px;
  border: 1px solid var(--reactor-yellow);
  color: var(--reactor-yellow);
  margin-bottom: 12px;
}
.feature-card:nth-child(2) .feature-tag { color: var(--plasma-magenta); border-color: var(--plasma-magenta); }
.feature-card:nth-child(3) .feature-tag { color: var(--circuit-cyan); border-color: var(--circuit-cyan); }
.feature-card:nth-child(4) .feature-tag { color: var(--ignition-orange); border-color: var(--ignition-orange); }
.feature-card h3 {
  font-size: 24px;
  letter-spacing: -0.01em;
  margin-bottom: 12px;
}
.feature-card p { font-size: 16px; }

/* Timeline */
.timeline-section {
  background: var(--voltage-black);
  padding: 96px 0;
}
.timeline-section .section-head { text-align: center; margin: 0 auto 56px; }
.timeline-section .section-head .eyebrow { color: var(--ignition-orange); }
.timeline-section .section-head p { margin: 16px auto 0; max-width: 560px; }
.timeline {
  position: relative;
  max-width: 1080px;
  margin: 0 auto;
  padding: 24px 0;
}
.timeline::before {
  content: '';
  position: absolute;
  left: 50%;
  top: 0;
  bottom: 0;
  width: 3px;
  background: var(--ignition-orange);
  transform: translateX(-50%);
}
.timeline-item {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 32px;
  margin-bottom: 56px;
}
.timeline-item:last-child { margin-bottom: 0; }
.timeline-node {
  width: 96px;
  height: 96px;
  border-radius: 50%;
  background: var(--ignition-orange);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-accent);
  font-size: 16px;
  letter-spacing: 0.05em;
  color: var(--voltage-black);
  text-align: center;
  z-index: 2;
  border: 4px solid var(--voltage-black);
  line-height: 1;
  padding: 6px;
}
.timeline-content { max-width: 340px; }
.timeline-content h3 {
  font-size: 22px;
  letter-spacing: -0.01em;
  margin-bottom: 8px;
}
.timeline-content p { font-size: 16px; }
.timeline-item.left .timeline-content { text-align: right; justify-self: end; }
.timeline-item.left > div:last-child { visibility: hidden; }
.timeline-item.right .timeline-content { text-align: left; justify-self: start; }
.timeline-item.right > div:first-child { visibility: hidden; }
.timeline-cta {
  text-align: center;
  margin-top: 56px;
}

/* CTA close (yellow panel) */
.cta-close {
  position: relative;
  background: var(--reactor-yellow);
  padding: 96px 0;
  text-align: center;
  overflow: hidden;
}
.cta-close .pattern-bg {
