/* ==========================================================================
   RESEARCH PAGE
   ========================================================================== */

.research-header {
  background: var(--voltage-black);
  padding: 96px 0 80px;
  position: relative;
  border-bottom: 3px solid var(--ignition-orange);
  overflow: hidden;
}
.research-header-grid {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 32px;
  align-items: center;
}
.research-header-left .eyebrow-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 1px solid var(--circuit-cyan);
  color: var(--circuit-cyan);
  padding: 6px 12px;
  font-family: var(--font-accent);
  font-size: 13px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  margin-bottom: 24px;
}
.research-header-left h1 {
  font-size: clamp(40px, 6.5vw, 80px);
  letter-spacing: -0.03em;
  line-height: 0.98;
}
.research-header-left h1 .yellow { color: var(--reactor-yellow); }
.research-header-left .sub {
  font-size: 18px;
  color: var(--poster-cream);
  max-width: 520px;
  margin-top: 20px;
}
.research-header-left .body {
  font-size: 16px;
  color: var(--poster-cream);
  max-width: 480px;
  margin-top: 16px;
  opacity: 0.9;
}
.research-illustration {
  position: relative;
  margin-right: -120px;
}
.research-illustration::before {
  content: '';
  position: absolute;
  inset: -10%;
  background: radial-gradient(circle, rgba(255, 31, 142, 0.3), transparent 60%);
  z-index: 0;
}
.research-illustration svg {
  position: relative;
  z-index: 2;
  width: 100%;
  max-width: 600px;
}

/* Projects list */
.projects-section {
  background: var(--voltage-black);
  padding: 80px 0;
}
.projects-section .section-head .eyebrow { color: var(--ignition-orange); }
.projects-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  margin-bottom: 48px;
}
.project-card {
  background: var(--backstage-charcoal);
  padding: 28px;
  border-top: 4px solid var(--ignition-orange);
  transition: all 0.2s ease;
}
.project-card:hover { border-top-color: var(--reactor-yellow); background: #252535; }
.project-card.last-card { max-width: calc(50% - 12px); }
.project-card h3 {
  font-size: 22px;
  letter-spacing: -0.02em;
  margin-bottom: 14px;
}
.project-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  margin-bottom: 14px;
}
.status-chip {
  background: var(--circuit-cyan);
  color: var(--voltage-black);
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 4px;
}
.status-chip.completed { background: var(--poster-cream); }
.division-text {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.18em;
  color: var(--plasma-magenta);
  text-transform: uppercase;
}
.lead-text {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.18em;
  color: var(--poster-cream);
  text-transform: uppercase;
}
.project-card p { font-size: 15px; line-height: 1.6; }

/* Research stats (signature gradient) */
.research-stats {
  background: linear-gradient(135deg, var(--plasma-magenta) 0%, var(--reactor-yellow) 100%);
  padding: 80px 0 96px;
  position: relative;
}
.research-stats .eyebrow { color: var(--voltage-black); display: block; margin-bottom: 8px; }
.research-stats h2 {
  color: var(--voltage-black);
  font-size: clamp(36px, 4.8vw, 52px);
  letter-spacing: -0.02em;
  margin-bottom: 48px;
}
.research-stat-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
  margin-bottom: 40px;
}
.research-stat .unit {
  font-family: var(--font-accent);
  font-size: 12px;
  letter-spacing: 0.2em;
  color: var(--voltage-black);
  text-transform: uppercase;
  margin-bottom: 4px;
}
.research-stat .num {
  font-family: var(--font-display);
  font-size: clamp(64px, 10vw, 128px);
  color: var(--crowd-white);
  letter-spacing: -0.04em;
  line-height: 0.95;
  margin-bottom: 8px;
}
.research-stat p { color: var(--voltage-black); font-size: 14px; line-height: 1.5; max-width: 200px; }

.dept-bar-chart {
  background: var(--voltage-black);
  padding: 24px;
  max-width: 720px;
}
.dept-bar-chart .chart-title {
  font-family: var(--font-accent);
  font-size: 13px;
  letter-spacing: 0.2em;
  color: var(--reactor-yellow);
  text-transform: uppercase;
  margin-bottom: 20px;
}
.bar-row {
  display: grid;
  grid-template-columns: 160px 1fr 60px;
  align-items: center;
  gap: 16px;
  margin-bottom: 14px;
}
.bar-label {
  font-family: var(--font-accent);
  font-size: 13px;
  letter-spacing: 0.1em;
  color: var(--crowd-white);
  text-transform: uppercase;
}
.bar-track {
  height: 32px;
  background: #2A2A3A;
  position: relative;
}
.bar-fill {
  height: 100%;
  background: var(--reactor-yellow);
  position: relative;
}
.bar-fill::after {
  content: '';
  position: absolute;
  right: -4px; top: 50%;
  transform: translateY(-50%);
  width: 8px; height: 8px;
  background: var(--ignition-orange);
}
.bar-value {
  font-family: var(--font-display);
  font-size: 18px;
  color: var(--reactor-yellow);
  text-align: right;
}

/* Gallery */
.gallery-section {
  background: var(--backstage-charcoal);
  padding: 80px 0;
  border-bottom: 3px solid var(--plasma-magenta);
}
.gallery-section .section-head .eyebrow { color: var(--reactor-yellow); }
.gallery-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}
.milestone-card {
  background: var(--voltage-black);
  border: 1px solid #2A2A3A;
  padding: 28px 28px 28px 28px;
  padding-top: 56px;
