.timeline {
  position: relative;
  max-width: 1080px;
  margin: 0 auto;
  padding: 24px 0;
}
.timeline::before {
  content: '';
  position: absolute;
  left: 50%;
  top: 0;
  bottom: 0;
  width: 3px;
  background: var(--ignition-orange);
  transform: translateX(-50%);
}
.timeline-item {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 32px;
  margin-bottom: 56px;
}
.timeline-item:last-child { margin-bottom: 0; }
.timeline-node {
  width: 96px;
  height: 96px;
  border-radius: 50%;
  background: var(--ignition-orange);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-accent);
  font-size: 16px;
  letter-spacing: 0.05em;
  color: var(--voltage-black);
  text-align: center;
  z-index: 2;
  border: 4px solid var(--voltage-black);
  line-height: 1;
  padding: 6px;
}
.timeline-content { max-width: 340px; }
