tool_use_result.originalFile:
/* ==========================================================================
   BOLTWORKS — Festival Poster Robotics Club
   Design tokens: Voltage Black, Reactor Yellow, Plasma Magenta,
                  Ignition Orange, Circuit Cyan, Poster Cream,
                  Crowd White, Backstage Charcoal
   ========================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Archivo+Black&family=Archivo:wght@400;500;700&family=Bebas+Neue&display=swap');

:root {
  --voltage-black: #0D0D0D;
  --reactor-yellow: #FFE600;
  --plasma-magenta: #FF1F8E;
  --ignition-orange: #FF5C00;
  --circuit-cyan: #00E5FF;
  --poster-cream: #F5F0DC;
  --crowd-white: #FFFFFF;
  --backstage-charcoal: #1E1E2A;

  --font-display: 'Archivo Black', 'Archivo', sans-serif;
  --font-body: 'Archivo', system-ui, sans-serif;
  --font-accent: 'Bebas Neue', 'Archivo', sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  background: var(--voltage-black);
  color: var(--crowd-white);
  line-height: 1.65;
  font-size: 17px;
  overflow-x: hidden;
}

img, svg { display: block; max-width: 100%; }

a { color: inherit; text-decoration: none; }

/* ---------- Utilities ---------- */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 32px;
}
.container-narrow { max-width: 960px; }
.container-wide { max-width: 1400px; }

.eyebrow {
  font-family: var(--font-accent);
  font-size: 13px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--plasma-magenta);
}

h1, h2, h3, h4 {
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: -0.03em;
  line-height: 0.98;
  color: var(--crowd-white);
}

p { color: var(--poster-cream); }

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-size: 15px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 18px 32px;
  border: 2px solid transparent;
  border-radius: 0;
  cursor: pointer;
  transition: all 0.18s ease;
  white-space: nowrap;
}
.btn-primary {
  background: var(--reactor-yellow);
  color: var(--voltage-black);
}
.btn-primary:hover {
  background: var(--plasma-magenta);
  color: var(--voltage-black);
}
.btn-outline {
  background: transparent;
  color: var(--crowd-white);
  border-color: var(--crowd-white);
}
.btn-outline:hover {
  color: var(--reactor-yellow);
  border-color: var(--reactor-yellow);
}
.btn-outline-yellow {
  background: transparent;
  color: var(--reactor-yellow);
  border-color: var(--reactor-yellow);
}
.btn-outline-yellow:hover {
  background: var(--reactor-yellow);
  color: var(--voltage-black);
}
.btn-dark {
  background: var(--voltage-black);
  color: var(--reactor-yellow);
}
.btn-dark:hover {
  background: var(--plasma-magenta);
  color: var(--crowd-white);
}
.btn-outline-dark {
  background: transparent;
  color: var(--voltage-black);
  border-color: var(--voltage-black);
}
.btn-outline-dark:hover {
  background: var(--voltage-black);
  color: var(--reactor-yellow);
}
.cta-row { display: flex; flex-wrap: wrap; gap: 16px; }

/* ---------- Top Navigation ---------- */
.site-nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13, 13, 13, 0.96);
  border-bottom: 2px solid var(--reactor-yellow);
  backdrop-filter: blur(8px);
}
.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 32px;
  max-width: 1400px;
  margin: 0 auto;
}
.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  font-family: var(--font-display);
  font-size: 22px;
  text-transform: uppercase;
  letter-spacing: -0.02em;
  color: var(--crowd-white);
}
.brand-bolt {
  width: 28px;
  height: 28px;
  fill: var(--reactor-yellow);
  flex-shrink: 0;
}
.brand-mark {
  background: var(--reactor-yellow);
  color: var(--voltage-black);
  padding: 4px 10px 2px;
}
.nav-links {
  display: flex;
  list-style: none;
  gap: 28px;
  align-items: center;
}
.nav-links a {
  font-family: var(--font-accent);
  font-size: 15px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  padding: 6px 4px;
  border-bottom: 2px solid transparent;
  transition: all 0.15s;
}
.nav-links a:hover { color: var(--reactor-yellow); }
.nav-links a.active {
  border-bottom-color: var(--plasma-magenta);
  color: var(--reactor-yellow);
}
.nav-cta {
  background: var(--reactor-yellow);
  color: var(--voltage-black) !important;
  padding: 8px 18px !important;
  border-bottom: none !important;
  font-family: var(--font-display) !important;
  letter-spacing: 0.04em !important;
}
.nav-cta:hover { background: var(--plasma-magenta); color: var(--crowd-white) !important; }
.nav-toggle {
  display: none;
  background: none;
  border: 2px solid var(--reactor-yellow);
  color: var(--reactor-yellow);
  font-family: var(--font-accent);
  padding: 6px 12px;
  font-size: 14px;
  cursor: pointer;
  letter-spacing: 0.15em;
}

/* ---------- Footer ---------- */
.site-footer {
  background: var(--backstage-charcoal);
  border-top: 4px solid var(--reactor-yellow);
  padding: 64px 32px 24px;
}
.footer-grid {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  padding-bottom: 48px;
  border-bottom: 1px solid #2A2A3A;
}
.footer-grid h4 {
  font-family: var(--font-accent);
  font-size: 14px;
  letter-spacing: 0.22em;
  color: var(--reactor-yellow);
  margin-bottom: 16px;
  font-weight: normal;
}
.footer-grid ul { list-style: none; }
.footer-grid li { margin-bottom: 8px; }
.footer-grid a {
  color: var(--poster-cream);
  font-size: 14px;
  transition: color 0.15s;
}
.footer-grid a:hover { color: var(--reactor-yellow); }
.footer-brand p {
  margin-top: 12px;
  max-width: 320px;
  font-size: 14px;
}
.footer-meta {
  max-width: 1280px;
  margin: 24px auto 0;
  display: flex;
  justify-content: space-between;
  font-family: var(--font-accent);
  font-size: 12px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--poster-cream);
}

/* ==========================================================================
   HOME PAGE
   ========================================================================== */

/* Hero */
.home-hero {
  position: relative;
  min-height: 100vh;
  background: var(--voltage-black);
  overflow: hidden;
  display: flex;
  align-items: center;
  padding: 120px 0 80px;
}
.home-hero::before {
  content: '';
  position: absolute;
  top: -10%;
  right: -10%;
  width: 70%;
  height: 80%;
  background: radial-gradient(circle, rgba(255, 31, 142, 0.18), transparent 60%);
  pointer-events: none;
}
.hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 40px;
  align-items: center;
  width: 100%;
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 48px;
}
.hero-text { position: relative; z-index: 2; }
.hero-text .eyebrow { color: var(--plasma-magenta); margin-bottom: 16px; display: block; }
.hero-headline {
  font-size: clamp(48px, 9vw, 96px);
  line-height: 0.95;
  letter-spacing: -0.03em;
  margin-bottom: 28px;
}
.hero-headline .word { display: block; }
.hero-headline .word-ignite { color: var(--reactor-yellow); }
.hero-sub {
  font-family: var(--font-display);
  text-transform: uppercase;
  font-size: clamp(16px, 1.6vw, 22px);
  color: var(--crowd-white);
  letter-spacing: -0.01em;
  margin-bottom: 20px;
  max-width: 540px;
}
.hero-body {
  max-width: 520px;
  margin-bottom: 40px;
  font-size: 17px;
}
.hero-visual {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-right: -120px;
}
.hero-visual svg {
  width: 100%;
  max-width: 640px;
  height: auto;
  filter: drop-shadow(0 30px 60px rgba(255, 31, 142, 0.25));
}

/* Stats band */
.stats-band {
  background: var(--backstage-charcoal);
  position: relative;
  padding: 48px 0;
  border-bottom: 2px solid var(--ignition-orange);
}
.stats-band .container { padding-left: 60px; padding-right: 32px; }
.stats-band .eyebrow {
  color: var(--circuit-cyan);
  text-align: center;
  display: block;
  margin-bottom: 12px;
}
.stats-band h2 {
  text-align: center;
  font-size: 28px;
  letter-spacing: -0.02em;
  margin-bottom: 40px;
}
.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}
.stat-cell .stat-num {
  font-family: var(--font-display);
  font-size: clamp(56px, 7vw, 88px);
  color: var(--reactor-yellow);
  line-height: 1;
  letter-spacing: -0.03em;
  margin-bottom: 8px;
}
.stat-cell p { font-size: 15px; max-width: 200px; line-height: 1.5; }

/* Feature grid */
.feature-grid-section {
  background: var(--voltage-black);
  padding: 96px 0;
}
.section-head { margin-bottom: 48px; max-width: 720px; }
.section-head .eyebrow { display: block; margin-bottom: 12px; }
.section-head h2 {
  font-size: clamp(32px, 5vw, 56px);
  letter-spacing: -0.02em;
}
.section-head p { margin-top: 16px; font-size: 18px; max-width: 600px; }

.feature-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  margin-bottom: 40px;
}
.feature-card {
  background: var(--backstage-charcoal);
  padding: 32px;
  position: relative;
  border-top: 4px solid var(--reactor-yellow);
  transition: all 0.2s ease;
}
.feature-card:nth-child(2) { border-top-color: var(--plasma-magenta); }
.feature-card:nth-child(3) { border-top-color: var(--circuit-cyan); }
.feature-card:nth-child(4) { border-top-color: var(--ignition-orange); }
.feature-card:hover { border-top-width: 6px; background: #25252F; }
.feature-tag {
  display: inline-block;
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  padding: 4px 10px;
  border: 1px solid var(--reactor-yellow);
  color: var(--reactor-yellow);
  margin-bottom: 12px;
}
.feature-card:nth-child(2) .feature-tag { color: var(--plasma-magenta); border-color: var(--plasma-magenta); }
.feature-card:nth-child(3) .feature-tag { color: var(--circuit-cyan); border-color: var(--circuit-cyan); }
.feature-card:nth-child(4) .feature-tag { color: var(--ignition-orange); border-color: var(--ignition-orange); }
.feature-card h3 {
  font-size: 24px;
  letter-spacing: -0.01em;
  margin-bottom: 12px;
}
.feature-card p { font-size: 16px; }

/* Timeline */
.timeline-section {
  background: var(--voltage-black);
  padding: 96px 0;
}
.timeline-section .section-head { text-align: center; margin: 0 auto 56px; }
.timeline-section .section-head .eyebrow { color: var(--ignition-orange); }
.timeline-section .section-head p { margin: 16px auto 0; max-width: 560px; }
.timeline {
  position: relative;
  max-width: 1080px;
  margin: 0 auto;
  padding: 24px 0;
}
.timeline::before {
  content: '';
  position: absolute;
  left: 50%;
  top: 0;
  bottom: 0;
  width: 3px;
  background: var(--ignition-orange);
  transform: translateX(-50%);
}
.timeline-item {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 32px;
  margin-bottom: 56px;
}
.timeline-item:last-child { margin-bottom: 0; }
.timeline-node {
  width: 96px;
  height: 96px;
  border-radius: 50%;
  background: var(--ignition-orange);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-accent);
  font-size: 16px;
  letter-spacing: 0.05em;
  color: var(--voltage-black);
  text-align: center;
  z-index: 2;
  border: 4px solid var(--voltage-black);
  line-height: 1;
  padding: 6px;
}
.timeline-content { max-width: 340px; }
.timeline-content h3 {
  font-size: 22px;
  letter-spacing: -0.01em;
  margin-bottom: 8px;
}
.timeline-content p { font-size: 16px; }
.timeline-item.left .timeline-content { text-align: right; justify-self: end; }
.timeline-item.left > div:last-child { visibility: hidden; }
.timeline-item.right .timeline-content { text-align: left; justify-self: start; }
.timeline-item.right > div:first-child { visibility: hidden; }
.timeline-cta {
  text-align: center;
  margin-top: 56px;
}

/* CTA close (yellow panel) */
.cta-close {
  position: relative;
  background: var(--reactor-yellow);
  padding: 96px 0;
  text-align: center;
  overflow: hidden;
}
.cta-close .pattern-bg {
  position: absolute;
  inset: 0;
  opacity: 0.12;
  pointer-events: none;
}
.cta-close .container { position: relative; }
.cta-close .eyebrow {
  color: rgba(13, 13, 13, 0.6);
  display: block;
  margin-bottom: 16px;
}
.cta-close h2 {
  font-size: clamp(40px, 7vw, 80px);
  color: var(--voltage-black);
  letter-spacing: -0.03em;
  line-height: 0.92;
  max-width: 900px;
  margin: 0 auto;
}
.cta-close .sub {
  font-family: var(--font-display);
  font-size: clamp(18px, 1.8vw, 22px);
  color: rgba(13, 13, 13, 0.82);
  text-transform: uppercase;
  letter-spacing: -0.01em;
  margin: 20px auto 40px;
  max-width: 700px;
}
.cta-close .cta-row { justify-content: center; }

/* ==========================================================================
   ABOUT PAGE
   ========================================================================== */

/* Page header with rotated mega-word */
.about-header {
  position: relative;
  background: var(--voltage-black);
  min-height: 80vh;
  padding: 120px 0 80px;
  overflow: hidden;
  border-bottom: 2px solid var(--reactor-yellow);
}
.mega-word {
  position: absolute;
  left: -40px;
  top: 50%;
  transform: translateY(-50%) rotate(-90deg);
  transform-origin: center;
  font-family: var(--font-display);
  font-size: 220px;
  color: var(--reactor-yellow);
  letter-spacing: -0.03em;
  line-height: 1;
  z-index: 0;
  white-space: nowrap;
  pointer-events: none;
  opacity: 0.95;
}
.about-header-inner {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: end;
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 48px;
}
.about-header-text {
  grid-column: 1 / -1;
  padding-left: 240px;
}
.about-header-text .eyebrow { color: var(--plasma-magenta); display: block; margin-bottom: 16px; }
.about-header-text h1 {
  font-size: clamp(40px, 7vw, 80px);
  letter-spacing: -0.03em;
  line-height: 0.95;
  max-width: 900px;
}
.about-header-text h1 .yellow { color: var(--reactor-yellow); }
.about-header-text .sub {
  font-family: var(--font-body);
  font-size: 20px;
  color: var(--poster-cream);
  margin-top: 24px;
  max-width: 700px;
}
.about-header-text .body {
  font-size: 17px;
  color: var(--poster-cream);
  max-width: 600px;
  margin-top: 20px;
}
.garage-illustration {
  position: absolute;
  right: 32px;
  bottom: -80px;
  width: 420px;
  z-index: 2;
}

/* Story / values */
.story-block {
  background: var(--backstage-charcoal);
  padding: 140px 0 100px;
}
.story-grid {
  display: grid;
  grid-template-columns: 5fr 7fr;
  gap: 64px;
  align-items: start;
}
.story-copy { position: relative; padding-right: 40px; border-right: 3px solid var(--ignition-orange); }
.story-copy .eyebrow { color: var(--ignition-orange); display: block; margin-bottom: 12px; }
.story-copy h2 {
  font-size: clamp(36px, 5vw, 56px);
  margin-bottom: 16px;
}
.story-copy .sub { font-size: 18px; color: var(--poster-cream); margin-bottom: 24px; }
.story-copy .body { font-size: 17px; color: var(--poster-cream); max-width: 380px; }

.values-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}
.value-card {
  background: var(--voltage-black);
  padding: 20px;
  border-top: 3px solid var(--plasma-magenta);
}
.value-tag {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.25em;
  color: var(--circuit-cyan);
  text-transform: uppercase;
  margin-bottom: 6px;
}
.value-card h3 {
  font-size: 22px;
  letter-spacing: -0.02em;
  margin-bottom: 10px;
}
.value-card p { font-size: 15px; line-height: 1.6; }

/* Team grid */
.team-section {
  background: var(--voltage-black);
  padding: 100px 0;
}
.team-section .section-head .eyebrow { color: var(--circuit-cyan); }
.team-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin: 60px 0 32px;
}
.team-card {
  background: var(--backstage-charcoal);
  padding: 20px;
  border-top: 4px solid var(--ignition-orange);
  position: relative;
}
.role-badge {
  display: inline-block;
  background: var(--circuit-cyan);
  color: var(--voltage-black);
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.25em;
  padding: 4px 8px;
  margin-bottom: 16px;
  text-transform: uppercase;
}
.team-name {
  font-family: var(--font-display);
  font-size: 22px;
  text-transform: uppercase;
  letter-spacing: -0.02em;
  color: var(--crowd-white);
  line-height: 1.05;
}
.team-name .first, .team-name .last { display: block; }
.team-divider {
  height: 1px;
  background: var(--ignition-orange);
  margin: 12px 0;
}
.team-card p { font-size: 15px; line-height: 1.6; }
.team-cta-row { display: flex; }

/* About stats (gradient) */
.about-stats {
  background: linear-gradient(135deg, var(--plasma-magenta) 0%, var(--reactor-yellow) 100%);
  padding: 100px 0;
}
.about-stats-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr;
  gap: 48px;
  align-items: center;
}
.about-stats-head .eyebrow { color: var(--voltage-black); display: block; margin-bottom: 16px; }
.about-stats-head h2 {
  font-size: clamp(36px, 5vw, 56px);
  color: var(--voltage-black);
  letter-spacing: -0.03em;
  margin-bottom: 48px;
}
.about-stat-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
}
.about-stat .rule {
  width: 40px;
  height: 2px;
  background: var(--voltage-black);
  margin-bottom: 8px;
}
.about-stat .num {
  font-family: var(--font-display);
  font-size: clamp(48px, 7vw, 96px);
  color: var(--crowd-white);
  letter-spacing: -0.04em;
  line-height: 0.95;
}
.about-stat .unit {
  font-family: var(--font-accent);
  font-size: 13px;
  letter-spacing: 0.2em;
  color: var(--voltage-black);
  text-transform: uppercase;
  margin-top: 6px;
}
.about-stat .desc {
  color: var(--voltage-black);
  font-size: 14px;
  line-height: 1.5;
  margin-top: 8px;
  max-width: 200px;
}
.growth-chart { background: var(--voltage-black); padding: 24px; }
.growth-chart .label {
  font-family: var(--font-accent);
  font-size: 12px;
  letter-spacing: 0.2em;
  color: var(--reactor-yellow);
  text-transform: uppercase;
  margin-bottom: 16px;
  text-align: center;
}

/* About CTA close */
.about-cta-close {
  background: var(--voltage-black);
  padding: 80px 0;
  text-align: center;
  border-top: 2px solid var(--reactor-yellow);
  border-bottom: 2px solid var(--reactor-yellow);
}
.about-cta-close .eyebrow { display: block; margin-bottom: 24px; }
.about-cta-close h2 {
  font-size: clamp(40px, 6vw, 72px);
  color: var(--reactor-yellow);
  letter-spacing: -0.03em;
  max-width: 900px;
  margin: 0 auto;
}
.about-cta-close .sub {
  color: var(--poster-cream);
  margin: 20px auto 32px;
  max-width: 540px;
  font-size: 18px;
}
.about-cta-close .cta-row { justify-content: center; }

/* ==========================================================================
   DEPARTMENTS PAGE
   ========================================================================== */

/* Page header masthead */
.dept-header {
  background: var(--voltage-black);
  padding: 100px 0 0;
  position: relative;
}
.dept-header-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 48px;
  align-items: start;
  padding-bottom: 48px;
}
.dept-header-left .eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
  color: var(--reactor-yellow);
}
.dept-header-left .eyebrow::before {
  content: '';
  width: 40px;
  height: 2px;
  background: var(--reactor-yellow);
}
.dept-header-left h1 {
  font-size: clamp(40px, 7vw, 88px);
  letter-spacing: -0.03em;
  line-height: 0.95;
}
.dept-header-left h1 .word-home { color: var(--reactor-yellow); }
.dept-header-right {
  padding-top: 80px;
}
.dept-header-right .sub {
  font-size: 18px;
  color: var(--poster-cream);
  margin-bottom: 24px;
}
.dept-header-right .body {
  font-size: 16px;
  color: var(--poster-cream);
}
.icon-strip {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 0;
  border-top: 1px solid #2A2A3A;
}
.icon-strip-item {
  aspect-ratio: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--backstage-charcoal);
  border-right: 1px solid var(--ignition-orange);
  border-top: 1px solid var(--ignition-orange);
  border-bottom: 1px solid var(--ignition-orange);
}
.icon-strip-item:first-child { border-left: 1px solid var(--ignition-orange); }
.icon-strip-item svg {
  width: 42px;
  height: 42px;
  color: var(--crowd-white);
  stroke: currentColor;
  fill: none;
  stroke-width: 2;
}

/* Departments grid */
.dept-grid-section {
  background: var(--voltage-black);
  position: relative;
  padding: 64px 0 80px;
  overflow: hidden;
}
.ghost-watermark {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  font-family: var(--font-accent);
  font-size: clamp(80px, 18vw, 220px);
  color: var(--reactor-yellow);
  opacity: 0.08;
  letter-spacing: -0.02em;
  white-space: nowrap;
  pointer-events: none;
  z-index: 0;
  text-transform: uppercase;
}
.dept-grid-section .section-head { position: relative; z-index: 2; }
.dept-grid-section .section-head .eyebrow { color: var(--reactor-yellow); }
.dept-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  position: relative;
  z-index: 2;
}
.dept-card {
  padding: 20px 16px;
  border-top: 3px solid var(--ignition-orange);
  transition: border-color 0.2s;
}
.dept-card:nth-child(odd) { background: var(--backstage-charcoal); }
.dept-card:nth-child(even) {
  background: var(--voltage-black);
  border: 1px solid var(--ignition-orange);
  border-top: 3px solid var(--ignition-orange);
}
.dept-card:hover { border-top-color: var(--reactor-yellow); }
